def encode(value):
    return (json.dumps(value, ensure_ascii=False, indent=2) + '\n').encode()

def build():
    base = dict(category='Class 9', subject='জীববিজ্ঞান', topic=TOPIC,
                book='SSC জীববিজ্ঞান — জীবন পাঠ: নিজস্ব প্রাথমিক অনুশীলনী',
                edition='প্রাথমিক খসড়া; Drive-এর ২০২৬ বইয়ের সঙ্গে মিলিয়ে দেখা বাকি',
                sourceUrl=SOURCE, lang='Bangla')
    def common(text, answer, section, difficulty='MEDIUM'):
        return dict(text=text, explanation=answer, page=f'ওয়েব সহায়ক পাঠ §{section}; মূল বইয়ের পৃষ্ঠা অযাচাইকৃত', difficulty=difficulty)
    mcq=[]
    for i,(stem,answer,distractors,why,section) in enumerate(MCQ):
        choices=list(distractors)
        choices.insert(i % 4, answer)
        mcq.append(dict(type='MCQ', **common(stem,why,section), options=dict(zip('ABCD',choices)), correct='ABCD'[i % 4]))
    sq=[dict(type='SQ', **common(stem,answer,section)) for stem,answer,section in SQ]
    cq=[dict(type='CQ', **common(stimulus,'নিজস্ব উদ্দীপকের নমুনা সমাধান নিচে; এটি বোর্ডের উত্তরমালা নয়।',section),
             parts=[dict(label=label, question=q, solution=a, marks=marks) for label,marks,(q,a) in zip('কখগঘ',[1,2,3,4],parts)])
        for stimulus,parts,section in CQ]
    files={f'{kind}.json':encode(dict(base,items=items)) for kind,items in [('mcq',mcq),('sq',sq),('cq',cq)]}
    manifest=dict(status='PROVISIONAL_DRAFT_NOT_IMPORTED', counts=dict(MCQ=len(mcq),SQ=len(sq),CQ=len(cq)),
                  originalPractice=True, parameterizedVariants=False, teacherCertified=False,
                  textbookChapterRead=False, wholeBookRead=False, sourceTextOnly=True,
                  originalBoardPaperVerified=False, officialYearVerified=False,
                  websiteImported=False, approved=False, published=False,
                  biologyAutoModelPolicyConfigured=False, figuresIncluded=0,
                  source=SOURCE, sourceSections=['1.1','1.2','1.2.1','1.2.2','1.3','1.4','1.5'],
                  files={name:dict(bytes=len(data),sha256=hashlib.sha256(data).hexdigest()) for name,data in files.items()})
    files['validation.json']=encode(manifest)
    return files

def main():
    parser=argparse.ArgumentParser()
    parser.add_argument('--check',action='store_true')
    args=parser.parse_args()
    files=build()
    for name,data in files.items():
        target=OUT/name
        if args.check:
            if not target.exists() or target.read_bytes()!=data:
                raise SystemExit(f'Generated draft differs: {name}')
        else:
            OUT.mkdir(parents=True,exist_ok=True)
            target.write_bytes(data)
    print('PASS: 30 MCQ / 10 SQ / 5 CQ; original provisional drafts only; no DB operations')

if __name__=='__main__':
    main()
